// Changes: Bound fixture scanning and check values while freeing returned token text even on mismatches.
// These program tests intentionally check non-layout lexemes only, not section 1.2
// indentation, EOL placement, or source positions. EOF/error tests use real stdin separately.
static void check_program(Ctx* ctx, const char* source,
                          const Token* expected, size_t count) {
  static const char sentinel[] = "\n@main ";
  array_clear(&ctx->lexer.buffer);
  array_clear(&ctx->lexer.stack);
  array_clear(&ctx->lexer.saved_stack);
  ctx->lexer.cursor = 0;
  size_t length = strlen(source);
  for (size_t i = 0; i < length; ++i)
    array_append(ctx, &ctx->lexer.buffer, (unsigned char)source[i]);
  for (size_t i = 0; i < sizeof(sentinel) - 1; ++i)
    array_append(ctx, &ctx->lexer.buffer, (unsigned char)sentinel[i]);

  size_t matched = 0;
  size_t text_offset = 0;
  for (size_t reads = 0; reads < length + sizeof(sentinel); ++reads) {
    Token actual = next_token(ctx);
    if (actual.type == INDENT || actual.type == EOL_TOKEN ||
        actual.type == WHITESPACE) {
      if (actual.value_type == TEXT) free(actual.value.text);
      continue;
    }
    if (matched == count) {
      if (actual.value_type == TEXT) free(actual.value.text);
      asserteq(actual.type, AT_MAIN);
      // A trailing unexpected token (even @main) cannot masquerade as the sentinel.
      asserteq(ctx->lexer.cursor, length + sizeof(sentinel) - 2);
      return;
    }
    const Token* wanted = &expected[matched];
    bool value_matches = actual.value_type == wanted->value_type;
    bool complete = true;
    if (value_matches) {
      switch (wanted->value_type) {
        case INTEGER: value_matches = actual.value.integer == wanted->value.integer; break;
        case DECIMAL: value_matches = actual.value.decimal == wanted->value.decimal; break;
        case TEXT: {
          // Literal portions of an interpolated string may span multiple tokens.
          // Compare their combined content, not an implementation-specific split.
          size_t remaining = strlen(wanted->value.text) - text_offset;
          size_t chunk = actual.value.text == NULL ? 0 : strlen(actual.value.text);
          if (wanted->type == STRING) {
            value_matches = actual.value.text != NULL && chunk <= remaining &&
                            memcmp(actual.value.text, wanted->value.text + text_offset, chunk) == 0;
            if (value_matches) text_offset += chunk;
            complete = text_offset == strlen(wanted->value.text);
          } else {
            value_matches = actual.value.text != NULL &&
                            strcmp(actual.value.text, wanted->value.text) == 0;
          }
          if (!value_matches)
            fprintf(stderr, "Expected text [%s], got [%s]\n", wanted->value.text,
                    actual.value.text == NULL ? "NULL" : actual.value.text);
          break;
        }
      }
    }
    if (actual.value_type == TEXT) free(actual.value.text);
    if (actual.type != wanted->type || !value_matches)
      fprintf(stderr, "Mock program token %zu: expected type %d, got %d (value match: %d)\n",
              matched, wanted->type, actual.type, value_matches);
    asserteq(actual.type, wanted->type);
    assert(value_matches);
    if (complete) {
      ++matched;
      text_offset = 0;
    }
  }
  fail("Mock program did not finish within its token budget");
}

